const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{position:relative;overflow:hidden}\n.qc-app{position:absolute;inset:0;box-sizing:border-box;padding:10px;display:flex;flex-direction:column;min-width:0;min-height:0;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.qc-app *{box-sizing:border-box;min-width:0}\n.qc-app button,.qc-app input{font:inherit;color:inherit}\n.view{display:flex;flex-direction:column;gap:8px;flex:1;min-height:0;min-width:0}\n.bar{display:flex;align-items:center;gap:8px;flex:none;min-height:26px}\n.ttl{flex:1;font-weight:700;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n\n.btn{appearance:none;display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:10px;padding:0 12px;min-height:32px;font-weight:600;cursor:pointer;white-space:nowrap;flex:none}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.ghost{background:transparent}\n.btn.danger{background:transparent;color:#B4533A;border-color:#B4533A}\n.btn.sm{min-height:26px;padding:0 9px;font-size:12px}\n.btn:disabled{opacity:.55;cursor:default}\n.btn:focus-visible,.inp:focus-visible,.row:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n\n.scroll{flex:1;min-height:0;overflow-x:hidden;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px;scrollbar-width:thin}\n.row{appearance:none;display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;text-align:left;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);border-radius:10px;padding:7px 9px;cursor:pointer;flex:none}\n.row-main{flex:1;display:flex;flex-direction:column;gap:1px;min-width:0}\n.row-name{font-weight:600;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}\n.row-meta{font-size:11px;color:var(--muted);overflow-wrap:anywhere}\n.row-amt{flex:none;margin-left:auto;font-weight:700;font-variant-numeric:tabular-nums;white-space:nowrap}\n\n.empty{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;padding:4px}\n.empty-t{font-weight:700;font-size:14px}\n.empty-s{font-size:12px;color:var(--muted)}\n\n.total{flex:none;display:flex;flex-direction:column;gap:2px;background:var(--accent);color:var(--on-accent);border-radius:12px;padding:8px 10px}\n.t-label{font-size:11px;opacity:.85}\n.t-amt{font-weight:800;line-height:1.15;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.t-amt.s1{font-size:26px}.t-amt.s2{font-size:22px}.t-amt.s3{font-size:19px}.t-amt.s4{font-size:16px}\n.t-break{display:flex;flex-wrap:wrap;gap:0 12px;font-size:11px;opacity:.9;font-variant-numeric:tabular-nums}\n\n.sec{display:flex;flex-direction:column;gap:6px;flex:none}\n.sec-rows{display:flex;flex-direction:column;gap:6px}\n.sec-h{display:flex;justify-content:space-between;align-items:baseline;gap:8px;font-size:12px;color:var(--muted);padding:2px 2px 0}\n.sec-t{font-weight:700;color:var(--ink)}\n.sec-sub{font-variant-numeric:tabular-nums;white-space:nowrap}\n.sec-empty{font-size:12px;color:var(--muted);padding:0 2px 4px}\n\n.manage{flex:none;display:flex;flex-direction:column;gap:6px;padding:6px 0 2px;border-top:1px dashed var(--line);margin-top:2px}\n.m-row{display:flex;flex-wrap:wrap;gap:6px}\n.m-note{font-size:12px;color:#B4533A}\n.p-acts,.f-acts{flex:none;display:flex;gap:8px}\n.p-acts .btn{flex:1}\n\n.fgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}\n.fgrid.k-plan{grid-template-columns:minmax(0,1fr)}\n.fgrid.k-cost{grid-template-columns:minmax(0,1fr)}\n.fld{display:flex;flex-direction:column;gap:3px}\n.fld.nm{grid-column:1/-1}\n.fld-l{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-height:32px;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);outline:none}\n.inp::placeholder{color:var(--muted);opacity:.7}\n.prev{font-weight:700;font-variant-numeric:tabular-nums;padding:2px 2px}\n.err{font-size:12px;color:#B4533A;font-weight:600}\n.toast{position:absolute;left:10px;right:10px;bottom:10px;padding:6px 9px;border-radius:8px;background:var(--panel-paper);border:1px solid #B4533A;color:#B4533A;font-size:12px;font-weight:600}\n\n\n/* 194x194\uff1a\u7d27\u51d1\uff0c\u603b\u989d\u5355\u884c\uff0c\u660e\u7ec6\u6eda\u52a8 */\n.card[data-size=\"3x3\"] .qc-app{padding:8px}\n.card[data-size=\"3x3\"] .view{gap:6px}\n.card[data-size=\"3x3\"] .bar{min-height:24px}\n.card[data-size=\"3x3\"] .ttl{font-size:13px}\n.card[data-size=\"3x3\"] .total{flex-direction:row;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:0 8px;padding:5px 9px}\n.card[data-size=\"3x3\"] .t-break{display:none}\n.card[data-size=\"3x3\"] .t-amt.s1{font-size:20px}\n.card[data-size=\"3x3\"] .t-amt.s2{font-size:18px}\n.card[data-size=\"3x3\"] .t-amt.s3{font-size:16px}\n.card[data-size=\"3x3\"] .t-amt.s4{font-size:14px}\n.card[data-size=\"3x3\"] .btn{min-height:28px;padding:0 8px}\n.card[data-size=\"3x3\"] .row{padding:5px 8px}\n.card[data-size=\"3x3\"] .row-date{display:none}\n.card[data-size=\"3x3\"] .inp{min-height:28px}\n.card[data-size=\"3x3\"] .fgrid{gap:6px}\n.card[data-size=\"3x3\"] .p-acts,.card[data-size=\"3x3\"] .f-acts{gap:6px}\n.card[data-size=\"3x3\"] .f-acts .btn{padding:0 4px}\n.card[data-size=\"3x3\"] .f-acts .btn.pri{flex:1.2}\n.card[data-size=\"3x3\"] .f-acts .btn:not(.pri){flex:1}\n\n/* 194x404\uff1a\u7ad6\u957f\uff0c\u4e0a\u603b\u989d\u4e0b\u660e\u7ec6 */\n.card[data-size=\"3x6\"] .qc-app{padding:12px}\n.card[data-size=\"3x6\"] .t-amt.s1{font-size:28px}\n\n/* 404x194\uff1a\u5de6\u4fa7\u603b\u989d\u4e0e\u64cd\u4f5c\uff0c\u53f3\u4fa7\u660e\u7ec6 */\n.card[data-size=\"6x3\"] .v-plan{display:grid;grid-template-columns:148px minmax(0,1fr);grid-template-rows:auto auto 1fr;grid-template-areas:\"head list\" \"total list\" \"acts list\";column-gap:12px;row-gap:8px}\n.card[data-size=\"6x3\"] .a-head{grid-area:head}\n.card[data-size=\"6x3\"] .a-total{grid-area:total}\n.card[data-size=\"6x3\"] .a-list{grid-area:list}\n.card[data-size=\"6x3\"] .a-acts{grid-area:acts;flex-direction:column;align-self:end}\n.card[data-size=\"6x3\"] .a-acts .btn{flex:none;min-height:28px}\n.card[data-size=\"6x3\"] .t-break{display:none}\n.card[data-size=\"6x3\"] .t-amt.s1{font-size:22px}\n.card[data-size=\"6x3\"] .t-amt.s2{font-size:19px}\n.card[data-size=\"6x3\"] .t-amt.s3{font-size:16px}\n.card[data-size=\"6x3\"] .t-amt.s4{font-size:14px}\n.card[data-size=\"6x3\"] .fgrid.k-work{grid-template-columns:minmax(0,2fr) minmax(0,1fr) minmax(0,1fr)}\n.card[data-size=\"6x3\"] .fgrid.k-work .nm{grid-column:auto}\n.card[data-size=\"6x3\"] .fgrid.k-cost{grid-template-columns:minmax(0,2fr) minmax(0,1fr)}\n.card[data-size=\"6x3\"] .fgrid.k-cost .nm{grid-column:auto}\n.card[data-size=\"6x3\"] .f-acts{justify-content:flex-start}\n\n/* 404x404\uff1a\u5bbd\u677e */\n.card[data-size=\"6x6\"] .qc-app{padding:16px}\n.card[data-size=\"6x6\"] .view{gap:12px}\n.card[data-size=\"6x6\"] .ttl{font-size:17px}\n.card[data-size=\"6x6\"] .total{padding:14px 16px}\n.card[data-size=\"6x6\"] .t-label{font-size:12px}\n.card[data-size=\"6x6\"] .t-amt.s1{font-size:38px}\n.card[data-size=\"6x6\"] .t-amt.s2{font-size:34px}\n.card[data-size=\"6x6\"] .t-amt.s3{font-size:30px}\n.card[data-size=\"6x6\"] .t-amt.s4{font-size:26px}\n.card[data-size=\"6x6\"] .t-break{font-size:13px}\n.card[data-size=\"6x6\"] .row{padding:10px 12px}\n.card[data-size=\"6x6\"] .row-meta{font-size:12px}\n.card[data-size=\"6x6\"] .scroll{gap:8px}\n.card[data-size=\"6x6\"] .fgrid.k-work{grid-template-columns:minmax(0,2fr) minmax(0,1fr) minmax(0,1fr)}\n.card[data-size=\"6x6\"] .fgrid.k-work .nm{grid-column:auto}\n.card[data-size=\"6x6\"] .fgrid.k-cost{grid-template-columns:minmax(0,2fr) minmax(0,1fr)}\n.card[data-size=\"6x6\"] .fgrid.k-cost .nm{grid-column:auto}\n.card[data-size=\"6x6\"] .inp{min-height:36px}\n";
function mount(ctx){
const {root,el,state,ui,commit,redraw,uid,day,size}=ctx;
const sz=size||(root.getAttribute&&root.getAttribute('data-size'))||'';
const listOf=s=>Array.isArray(s&&s.plans)?s.plans:[];
const plans=listOf(state);
const R=n=>Math.round((Number(n)||0)*100)/100;
function money(n){
  const v=R(n);
  const parts=Math.abs(v).toFixed(2).split('.');
  return (v<0?'-':'')+'¥'+parts[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+parts[1];
}
function num(n){return String(Math.round((Number(n)||0)*100)/100);}
function parseNum(v){
  const t=String(v==null?'':v).trim();
  if(t==='')return NaN;
  return Number(t);
}
const okNum=v=>isFinite(v)&&v>=0&&v<=1e9;
const h=(tag,attrs,...c)=>el(tag,attrs||{},...c.flat(2).filter(x=>x!==null&&x!==undefined&&x!==false));
const btn=(label,onclick,cls,extra)=>h('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick},extra||{}),label);
const amtCls=s=>{const n=s.length;return n<=9?'s1':n<=11?'s2':n<=13?'s3':'s4';};

const workAmt=w=>R((Number(w.hours)||0)*(Number(w.rate)||0));
function totals(p){
  const wk=(p.work||[]).reduce((a,w)=>a+workAmt(w),0);
  const cs=(p.costs||[]).reduce((a,c)=>a+R(c.amount),0);
  return {work:R(wk),cost:R(cs),total:R(wk+cs)};
}
function upsert(arr,item){
  const a=arr||[];
  return a.some(x=>x.id===item.id)?a.map(x=>x.id===item.id?item:x):a.concat([item]);
}
function mapPlan(s,id,fn){
  return Object.assign({},s,{plans:listOf(s).map(p=>p.id===id?Object.assign({},fn(p),{updatedAt:day()}):p)});
}

function go(patch){
  Object.assign(ui,{err:'',confirm:null},patch);
  redraw();
}
function failMsg(msg){
  ui.busy=false;
  if(ui.form){ui.form.busy=false;ui.form.err=msg;}else{ui.err=msg;}
  redraw();
}
function run(apply,next,msg){
  return commit(apply,Object.assign({err:'',confirm:null,form:null,busy:false},next))
    .then(ok=>{if(ok===false)failMsg(msg);})
    .catch(()=>failMsg(msg));
}

function openPlanForm(p){
  go({form:{kind:'plan',planId:p?p.id:null,id:p?p.id:uid(),isNew:!p,draft:{name:p?p.name:''}}});
}
function openWorkForm(p,w){
  go({form:{kind:'work',planId:p.id,id:w?w.id:uid(),isNew:!w,
    draft:{name:w?w.name:'',hours:w?String(w.hours):'',rate:w?String(w.rate):''}}});
}
function openCostForm(p,c){
  go({form:{kind:'cost',planId:p.id,id:c?c.id:uid(),isNew:!c,
    draft:{name:c?c.name:'',amount:c?String(c.amount):''}}});
}

function dupPlan(p){
  if(ui.busy)return;
  ui.busy=true;
  const id=uid();
  const copy={id,name:p.name+'（副本）',
    work:(p.work||[]).map(w=>Object.assign({},w,{id:uid()})),
    costs:(p.costs||[]).map(c=>Object.assign({},c,{id:uid()})),
    createdAt:day(),updatedAt:day()};
  run(s=>Object.assign({},s,{plans:listOf(s).concat([copy])}),{view:'plan',planId:id},'复制失败，请重试');
}
function delPlan(id){
  if(ui.busy)return;
  ui.busy=true;
  run(s=>Object.assign({},s,{plans:listOf(s).filter(p=>p.id!==id)}),{view:'list',planId:null},'删除失败，请重试');
}


function planRow(p){
  const t=totals(p);
  return h('button',{type:'button',class:'row',onclick:()=>go({view:'plan',planId:p.id})},
    h('span',{class:'row-main'},
      h('span',{class:'row-name'},p.name),
      h('span',{class:'row-meta'},(p.work||[]).length+' 项工作 · '+(p.costs||[]).length+' 项成本',
        p.updatedAt?h('span',{class:'row-date'},' · '+p.updatedAt):null)),
    h('span',{class:'row-amt'},money(t.total)));
}
function renderList(){
  const head=h('div',{class:'bar'},
    h('div',{class:'ttl'},'报价方案'),
    plans.length?btn('＋ 新建',()=>openPlanForm(null),'pri sm'):null);
  const body=plans.length
    ?h('div',{class:'scroll'},plans.map(planRow))
    :h('div',{class:'empty'},
      h('div',{class:'empty-t'},'还没有报价方案'),
      h('div',{class:'empty-s'},'每个方案单独保存工作小时、时薪和直接成本。'),
      btn('新建报价方案',()=>openPlanForm(null),'pri'));
  return h('div',{class:'view v-list'},head,body);
}

function workRow(p,w){
  return h('button',{type:'button',class:'row',onclick:()=>openWorkForm(p,w)},
    h('span',{class:'row-main'},
      h('span',{class:'row-name'},w.name),
      h('span',{class:'row-meta'},num(w.hours)+' 小时 × '+money(w.rate)+'/小时')),
    h('span',{class:'row-amt'},money(workAmt(w))));
}
function costRow(p,c){
  return h('button',{type:'button',class:'row',onclick:()=>openCostForm(p,c)},
    h('span',{class:'row-main'},h('span',{class:'row-name'},c.name)),
    h('span',{class:'row-amt'},money(R(c.amount))));
}
function section(title,sub,rows,emptyText){
  return h('div',{class:'sec'},
    h('div',{class:'sec-h'},h('span',{class:'sec-t'},title),h('span',{class:'sec-sub'},sub)),
    rows.length?h('div',{class:'sec-rows'},rows):h('div',{class:'sec-empty'},emptyText));
}

function renderPlan(p){
  const t=totals(p);
  const tm=money(t.total);
  const head=h('div',{class:'bar a-head'},
    btn('‹ 返回',()=>go({view:'list',planId:null}),'ghost sm',{'aria-label':'返回方案列表'}),
    h('div',{class:'ttl',title:p.name},p.name));
  const total=h('div',{class:'total a-total'},
    h('div',{class:'t-label'},'总报价（人民币）'),
    h('div',{class:'t-amt '+amtCls(tm)},tm),
    h('div',{class:'t-break'},
      h('span',null,'人工 '+money(t.work)),
      h('span',null,'直接成本 '+money(t.cost))));
  const manage=h('div',{class:'manage'},
    ui.confirm==='delPlan'
      ?[h('div',{class:'m-note'},'！删除后该方案的全部明细无法恢复，确认删除？'),
        h('div',{class:'m-row'},
          btn('确认删除',()=>delPlan(p.id),'danger sm'),
          btn('取消',()=>go({confirm:null}),'ghost sm'))]
      :h('div',{class:'m-row'},
        btn('重命名',()=>openPlanForm(p),'ghost sm'),
        btn('复制方案',()=>dupPlan(p),'ghost sm'),
        btn('删除方案',()=>go({confirm:'delPlan'}),'ghost sm')));
  const list=h('div',{class:'scroll a-list'},
    section('工作明细','小计 '+money(t.work),(p.work||[]).map(w=>workRow(p,w)),'暂无工作项，点下方添加'),
    section('直接成本','小计 '+money(t.cost),(p.costs||[]).map(c=>costRow(p,c)),'暂无，可添加材料等直接成本'),
    manage);
  const acts=h('div',{class:'p-acts a-acts'},
    btn('＋ 工作项',()=>openWorkForm(p,null),'pri'),
    btn(sz==='3x3'?'＋ 成本项':'＋ 直接成本',()=>openCostForm(p,null),'pri'));
  return h('div',{class:'view v-plan'},head,total,list,acts);
}


function submitForm(){
  const f=ui.form;
  if(!f||f.busy)return;
  const d=f.draft;
  const name=String(d.name||'').trim();
  const bad=m=>{f.err=m;redraw();};
  if(!name)return bad('请先填写名称');
  const pid=f.planId,id=f.id;
  let apply;
  const next={view:'plan',planId:pid};
  if(f.kind==='plan'){
    apply=s=>{
      const ps=listOf(s);
      if(ps.some(p=>p.id===id)){
        return Object.assign({},s,{plans:ps.map(p=>p.id===id?Object.assign({},p,{name,updatedAt:day()}):p)});
      }
      return Object.assign({},s,{plans:ps.concat([{id,name,work:[],costs:[],createdAt:day(),updatedAt:day()}])});
    };
    next.planId=id;
  }else if(f.kind==='work'){
    const hrs=parseNum(d.hours),rate=parseNum(d.rate);
    if(!okNum(hrs))return bad('请填写有效的预计小时数（不小于 0）');
    if(!okNum(rate))return bad('请填写有效的时薪（不小于 0）');
    const item={id,name,hours:hrs,rate};
    apply=s=>mapPlan(s,pid,p=>Object.assign({},p,{work:upsert(p.work,item)}));
  }else{
    const amt=parseNum(d.amount);
    if(!okNum(amt))return bad('请填写有效的金额（不小于 0）');
    const item={id,name,amount:amt};
    apply=s=>mapPlan(s,pid,p=>Object.assign({},p,{costs:upsert(p.costs,item)}));
  }
  f.busy=true;
  f.err='';
  run(apply,next,'保存失败，请重试');
}
function deleteItem(){
  const f=ui.form;
  if(!f||f.busy)return;
  if(!f.confirmDel){f.confirmDel=true;redraw();return;}
  const pid=f.planId,id=f.id,isWork=f.kind==='work';
  f.busy=true;
  run(s=>mapPlan(s,pid,p=>isWork
    ?Object.assign({},p,{work:(p.work||[]).filter(x=>x.id!==id)})
    :Object.assign({},p,{costs:(p.costs||[]).filter(x=>x.id!==id)})),
    {view:'plan',planId:pid},'删除失败，请重试');
}

function renderForm(){
  const f=ui.form,d=f.draft;
  const spec=f.kind==='plan'
    ?[['name','方案名称','text','如：基础版']]
    :f.kind==='work'
      ?[['name','工作项名称','text','如：界面设计'],['hours','预计小时','number','0'],['rate','时薪（元/小时）','number','0']]
      :[['name','成本名称','text','如：材料费'],['amount','金额（元）','number','0']];
  const title=f.kind==='plan'?(f.isNew?'新建报价方案':'重命名方案')
    :f.kind==='work'?(f.isNew?'添加工作项':'编辑工作项')
    :(f.isNew?'添加直接成本':'编辑直接成本');
  const prev=h('div',{class:'prev'});
  const refresh=()=>{
    if(f.kind!=='work')return;
    const a=parseNum(d.hours),b=parseNum(d.rate);
    prev.textContent='本项小计 '+(okNum(a)&&okNum(b)?money(R(a*b)):'—');
  };
  refresh();
  const fields=spec.map(sp=>{
    const k=sp[0],isNum=sp[2]==='number';
    const attrs={class:'inp',type:sp[2],value:d[k]==null?'':String(d[k]),placeholder:sp[3],
      oninput:e=>{d[k]=e.target.value;refresh();},
      onkeydown:e=>{if(e.key==='Enter'){e.preventDefault();submitForm();}}};
